import json
import os


class JSONProcessor:
    FILE_NOT_FOUND = 0
    PROCESS_ERROR = -1
    SUCCESS = 1
    KEY_NOT_FOUND = 0

    def read_json(self, file_path):
        if not os.path.exists(file_path):
            return self.FILE_NOT_FOUND
        try:
            with open(file_path, 'r') as file:
                data = json.load(file)
            return data
        except Exception:
            return self.PROCESS_ERROR

    def write_json(self, data, file_path):
        try:
            with open(file_path, 'w') as file:
                json.dump(data, file)
            return self.SUCCESS
        except Exception:
            return self.PROCESS_ERROR

    def process_json(self, file_path, remove_key):
        data = self.read_json(file_path)
        if data == self.FILE_NOT_FOUND or data == self.PROCESS_ERROR:
            return self.KEY_NOT_FOUND
        if self.contains_key(data, remove_key):
            self.remove_key_from_data(data, remove_key)
            self.write_json(data, file_path)
            return self.SUCCESS
        return self.KEY_NOT_FOUND

    def contains_key(self, data, key):
        return key in data

    def remove_key_from_data(self, data, key):
        del data[key]
